show() {
  if (this.active) {
    return;
  }

  const {datepicker, element} = this;
  const inputField = datepicker.inputField;
  if (inputField) {
    // ensure picker's direction matches input's
    const inputDirection = getTextDirection(inputField);
    if (inputDirection !== getTextDirection(getParent(element))) {
      element.dir = inputDirection;
    } else if (element.dir) {
      element.removeAttribute('dir');
    }

    element.style.visibility = 'hidden';
    element.classList.add('active');
    this.place();
    element.style.visibility = '';

    if (datepicker.config.disableTouchKeyboard) {
      inputField.blur();
    }

    // ADD OUR LISTENER FOR TAB KEY TO MOVE FOCUS TO THE NEXT FOCUSABLE ELEMENT
    // Remove any existing listener to avoid duplicates
    if (this._tabKeyHandler) {
      this.element.removeEventListener('keydown', this._tabKeyHandler);
    }
    this._tabKeyHandler = (e) => {
      if (e.key === 'Tab') {
        let next = this.element.nextElementSibling;
        while (next) {
          const focusable = 
            next.tagName.match(/^(input|select|textarea|button|object)$/i) ||
            (next.hasAttribute('tabindex') && next.tabIndex >= 0);
          if (focusable && !next.disabled) {
            try {
              next.focus();
            } catch (err) {
              // ignore and continue
            }
            if (document.activeElement === next) {
              break;
            }
          }
          next = next.nextElementSibling;
        }
        e.preventDefault();
      }
    };
    this.element.addEventListener('keydown', this._tabKeyHandler);
  } else {
    element.classList.add('active');
  }
  this.active = true;
  triggerDatepickerEvent(datepicker, 'show');
}

